import { test, expect } from '@playwright/test';

test.beforeEach(async ({ page }) => {
  await page.goto('/login'); // Assuming your app runs on a base URL configured in playwright.config.ts
});

test('has title', async ({ page }) => {
  await expect(page).toHaveTitle(/SynapsePlan/);
});

test('allows user to login', async ({ page }) => {
  await page.fill('input[name="email"]', 'test@example.com');
  await page.fill('input[name="password"]', 'password123');
  await page.click('button:has-text("Sign In")');

  // Assuming successful login redirects to dashboard
  await expect(page).toHaveURL(/.*dashboard/);
  await expect(page.getByText('Welcome, test@example.com!')).toBeVisible();
});

test('shows error on invalid login', async ({ page }) => {
  await page.fill('input[name="email"]', 'test@example.com');
  await page.fill('input[name="password"]', 'wrongpassword');
  await page.click('button:has-text("Sign In")');

  // Assuming an error message appears
  await expect(page.getByText('Incorrect username or password')).toBeVisible();
});
